class StubDefinition:
    """Loaded stub definition rules from stub_definition.yaml."""
    stub_patterns: Dict[str, Any]
    high_signal_definition: Dict[str, Any]
    allowlist_minimal_modules: List[str]
    exempt_domains: List[str]
    exempt_paths: List[str]
    classification_thresholds: Dict[str, float]
    target_domains: List[str]
    file_extensions: List[str]
    max_file_size: int


def load_stub_definition() -> StubDefinition:
    """Load stub definition from YAML file."""
    if not STUB_DEFINITION_PATH.exists():
        raise FileNotFoundError(f"stub_definition.yaml not found at {STUB_DEFINITION_PATH}")
    
    with STUB_DEFINITION_PATH.open("r", encoding="utf-8") as f:
        data = yaml.safe_load(f)
    
    scanner_config = data.get("scanner_config", {})
    
    return StubDefinition(
        stub_patterns=data.get("stub_patterns", {}),
        high_signal_definition=data.get("high_signal_definition", {}),
        allowlist_minimal_modules=data.get("allowlist_minimal_modules", []),
        exempt_domains=data.get("exempt_domains", []),
        exempt_paths=data.get("exempt_paths", []),
        classification_thresholds=data.get("classification_thresholds", {}),
        target_domains=scanner_config.get("target_domains", []),
        file_extensions=scanner_config.get("file_extensions", [".py"]),
        max_file_size=scanner_config.get("max_file_size", 1048576),
    )


class ASTAnalysis:
    """Results of AST analysis for a Python file."""
    has_syntax_error: bool
    total_nodes: int
    class_count: int
    function_count: int
    has_executable_statements: bool
    has_only_pass_ellipsis_docstring: bool
    empty_function_bodies: int
    empty_class_bodies: int
    placeholder_markers_found: List[str]
    non_comment_token_count: int


def count_non_comment_tokens(source: str) -> int:
    """Count non-comment tokens in Python source code."""
    try:
        tokens = list(tokenize.generate_tokens(StringIO(source).readline))
        # Exclude comments, newlines, encoding, and endmarker
        meaningful_tokens = [
            t for t in tokens
            if t.type not in (
                tokenize.COMMENT,
                tokenize.NL,
                tokenize.NEWLINE,
                tokenize.ENCODING,
                tokenize.ENDMARKER,
                tokenize.INDENT,
                tokenize.DEDENT,
            )
        ]
        return len(meaningful_tokens)
    except tokenize.TokenizeError:
        # Fallback: rough word count
        return len(source.split())


def is_executable_statement(node: ast.AST) -> bool:
    """Check if an AST node represents an executable statement."""
    # Pass, Ellipsis, and docstrings are not executable
    if isinstance(node, ast.Pass):
        return False
    if isinstance(node, ast.Expr):
        if isinstance(node.value, (ast.Constant, ast.Ellipsis)):
            # Docstring or ellipsis
            return False
    # Import statements are not "executable" in the implementation sense
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        return False
    return True


def has_executable_body(body: List[ast.stmt]) -> bool:
    """Check if a function/class body has executable statements."""
    for stmt in body:
        if is_executable_statement(stmt):
            return True
    return False


def analyze_ast(source: str) -> ASTAnalysis:
    """Analyze Python source code AST."""
    placeholder_markers = []
    
    # Check for placeholder markers in source
    marker_patterns = ["STUB", "TODO", "TBD", "PHASE1", "REPAIR", "PLACEHOLDER", "NOT_IMPLEMENTED", "FIXME"]
    source_upper = source.upper()
    for marker in marker_patterns:
        if marker in source_upper:
            placeholder_markers.append(marker)
    
    # Count non-comment tokens
    non_comment_token_count = count_non_comment_tokens(source)
    
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return ASTAnalysis(
            has_syntax_error=True,
            total_nodes=0,
            class_count=0,
            function_count=0,
            has_executable_statements=False,
            has_only_pass_ellipsis_docstring=True,
            empty_function_bodies=0,
            empty_class_bodies=0,
            placeholder_markers_found=placeholder_markers,
            non_comment_token_count=non_comment_token_count,
        )
    
    total_nodes = sum(1 for _ in ast.walk(tree))
    class_count = 0
    function_count = 0
    empty_function_bodies = 0
    empty_class_bodies = 0
    has_executable = False
    
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            class_count += 1
            if not has_executable_body(node.body):
                empty_class_bodies += 1
            else:
                has_executable = True
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            function_count += 1
            if not has_executable_body(node.body):
                empty_function_bodies += 1
            else:
                has_executable = True
    
    # Check if module body has only pass/ellipsis/docstring
    has_only_pass_ellipsis = True
    for stmt in tree.body:
        if is_executable_statement(stmt):
            has_only_pass_ellipsis = False
            has_executable = True
            break
    
    return ASTAnalysis(
        has_syntax_error=False,
        total_nodes=total_nodes,
        class_count=class_count,
        function_count=function_count,
        has_executable_statements=has_executable,
        has_only_pass_ellipsis_docstring=has_only_pass_ellipsis,
        empty_function_bodies=empty_function_bodies,
        empty_class_bodies=empty_class_bodies,
        placeholder_markers_found=placeholder_markers,
        non_comment_token_count=non_comment_token_count,
    )


class FileClassification:
    """Classification result for a single file."""
    path: str
    relative_path: str
    domain: str
    is_stub: bool
    is_high_signal: bool
    stub_reasons: List[str]
    high_signal_reasons: List[str]
    is_allowlisted: bool
    is_exempt: bool
    ast_analysis: Optional[Dict[str, Any]]
    confidence: float


def is_path_exempt(path: Path, exempt_paths: List[str]) -> bool:
    """Check if path matches any exempt glob patterns."""
    path_str = str(path).replace("\\", "/")
    for pattern in exempt_paths:
        # Simple glob matching
        regex_pattern = pattern.replace("**", ".*").replace("*", "[^/]*")
        if re.search(regex_pattern, path_str):
            return True
    return False


def is_allowlisted(filename: str, allowlist: List[str]) -> bool:
    """Check if filename is in the allowlist."""
    for pattern in allowlist:
        if pattern.startswith("*"):
            # Glob pattern like *.pyi
            if filename.endswith(pattern[1:]):
                return True
        elif filename == pattern:
            return True
    return False


def classify_file(
    path: Path,
    domain: str,
    stub_def: StubDefinition,
) -> FileClassification:
    """Classify a single Python file as stub or high-signal."""
    relative_path = str(path.relative_to(PROJECT_ROOT)).replace("\\", "/")
    filename = path.name
    
    # Check exemptions
    if domain in stub_def.exempt_domains:
        return FileClassification(
            path=str(path),
            relative_path=relative_path,
            domain=domain,
            is_stub=False,
            is_high_signal=False,
            stub_reasons=[],
            high_signal_reasons=[],
            is_allowlisted=False,
            is_exempt=True,
            ast_analysis=None,
            confidence=1.0,
        )
    
    if is_path_exempt(path, stub_def.exempt_paths):
        return FileClassification(
            path=str(path),
            relative_path=relative_path,
            domain=domain,
            is_stub=False,
            is_high_signal=False,
            stub_reasons=[],
            high_signal_reasons=[],
            is_allowlisted=False,
            is_exempt=True,
            ast_analysis=None,
            confidence=1.0,
        )
    
    # Check allowlist
    allowlisted = is_allowlisted(filename, stub_def.allowlist_minimal_modules)
    
    # Read file content
    try:
        source = path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return FileClassification(
            path=str(path),
            relative_path=relative_path,
            domain=domain,
            is_stub=True,
            is_high_signal=False,
            stub_reasons=["unreadable_file"],
            high_signal_reasons=[],
            is_allowlisted=allowlisted,
            is_exempt=False,
            ast_analysis=None,
            confidence=0.5,
        )
    
    # Analyze AST
    ast_result = analyze_ast(source)
    
    # Classify
    stub_reasons: List[str] = []
    high_signal_reasons: List[str] = []
    
    # Check stub patterns
    patterns = stub_def.stub_patterns
    
    # Empty or whitespace only
    if patterns.get("empty_or_whitespace_only") and not source.strip():
        stub_reasons.append("empty_or_whitespace_only")
    
    # AST only pass/ellipsis/docstring
    if patterns.get("ast_only_pass_ellipsis_docstring") and ast_result.has_only_pass_ellipsis_docstring:
        stub_reasons.append("ast_only_pass_ellipsis_docstring")
    
    # Placeholder markers
    if ast_result.placeholder_markers_found:
        stub_reasons.append(f"placeholder_markers:{','.join(ast_result.placeholder_markers_found)}")
    
    # Empty function/class bodies
    if patterns.get("empty_function_body") and ast_result.empty_function_bodies > 0:
        stub_reasons.append(f"empty_function_bodies:{ast_result.empty_function_bodies}")
    
    if patterns.get("empty_class_body") and ast_result.empty_class_bodies > 0:
        stub_reasons.append(f"empty_class_bodies:{ast_result.empty_class_bodies}")
    
    # Min token threshold
    min_tokens = patterns.get("min_token_threshold", 10)
    if ast_result.non_comment_token_count < min_tokens:
        stub_reasons.append(f"below_min_tokens:{ast_result.non_comment_token_count}<{min_tokens}")
    
    # Check high-signal definition
    hs_def = stub_def.high_signal_definition
    
    if hs_def.get("has_executable_class_or_function") and ast_result.has_executable_statements:
        high_signal_reasons.append("has_executable_statements")
    
    min_non_comment = hs_def.get("min_non_comment_tokens", 120)
    if ast_result.non_comment_token_count >= min_non_comment:
        high_signal_reasons.append(f"token_count:{ast_result.non_comment_token_count}>={min_non_comment}")
    
    # Determine final classification
    is_stub = len(stub_reasons) > 0 and not allowlisted
    is_high_signal = len(high_signal_reasons) > 0
    
    # If high-signal, override stub classification (unless critical stub markers)
    if is_high_signal and is_stub:
        # Only keep stub if it has critical markers
        critical_markers = {"STUB", "PLACEHOLDER", "NOT_IMPLEMENTED"}
        has_critical = any(
            m in critical_markers
            for m in ast_result.placeholder_markers_found
        )
        if not has_critical:
            is_stub = False
    
    # Calculate confidence
    confidence = 0.5
    if is_stub:
        confidence = min(0.5 + len(stub_reasons) * 0.15, 0.95)
    elif is_high_signal:
        confidence = min(0.5 + len(high_signal_reasons) * 0.2, 0.95)
    
    return FileClassification(
        path=str(path),
        relative_path=relative_path,
        domain=domain,
        is_stub=is_stub,
        is_high_signal=is_high_signal,
        stub_reasons=stub_reasons,
        high_signal_reasons=high_signal_reasons,
        is_allowlisted=allowlisted,
        is_exempt=False,
        ast_analysis=asdict(ast_result),
        confidence=confidence,
    )


class StubAuditResult:
    """Complete stub audit result."""
    timestamp: str
    phase: str
    mode: str
    stub_count_per_domain: Dict[str, int]
    canonical_stub_count: int
    total_files_scanned: int
    stub_files: List[Dict[str, Any]]
    high_signal_files: List[Dict[str, Any]]
    exempt_files_count: int
    allowlisted_files_count: int
    high_signal_misclassifications: List[Dict[str, Any]]
    validation_keys: Dict[str, str]


def scan_domain(domain: str, stub_def: StubDefinition) -> List[FileClassification]:
    """Scan a single domain for stubs."""
    domain_root = PROJECT_ROOT / domain
    if not domain_root.exists():
        return []
    
    results: List[FileClassification] = []
    
    for ext in stub_def.file_extensions:
        for path in domain_root.rglob(f"*{ext}"):
            if not path.is_file():
                continue
            
            # Skip system directories
            if any(excl in path.parts for excl in ["__pycache__", ".pytest_cache", ".mypy_cache"]):
                continue
            
            # Skip files exceeding max size
            try:
                if path.stat().st_size > stub_def.max_file_size:
                    continue
            except OSError:
                continue
            
            classification = classify_file(path, domain, stub_def)
            results.append(classification)
    
    return results


def run_stub_scan() -> StubAuditResult:
    """Run the complete stub scan across all target domains."""
    logging.debug("=== PHASE 3A — STUB SCANNER (READ-ONLY) ===")
    logging.debug(f"Project root: {PROJECT_ROOT}")
    logging.debug(f"Output path: {OUTPUT_PATH}")
    
    # Load stub definition
    stub_def = load_stub_definition()
    logging.debug(f"Target domains: {stub_def.target_domains}")
    logging.debug(f"Exempt domains: {stub_def.exempt_domains}")
    
    all_classifications: List[FileClassification] = []
    stub_count_per_domain: Dict[str, int] = {}
    
    for domain in stub_def.target_domains:
        logging.debug(f"Scanning domain: {domain}")
        classifications = scan_domain(domain, stub_def)
        all_classifications.extend(classifications)
        
        stub_count = sum(1 for c in classifications if c.is_stub and not c.is_exempt)
        stub_count_per_domain[domain] = stub_count
        logging.debug(f"  Files scanned: {len(classifications)}, Stubs found: {stub_count}")
    
    # Aggregate results
    stub_files = [asdict(c) for c in all_classifications if c.is_stub and not c.is_exempt]
    high_signal_files = [asdict(c) for c in all_classifications if c.is_high_signal]
    exempt_count = sum(1 for c in all_classifications if c.is_exempt)
    allowlisted_count = sum(1 for c in all_classifications if c.is_allowlisted)
    
    # Canonical stub count (excluding exempt domains)
    canonical_stub_count = sum(
        count for domain, count in stub_count_per_domain.items()
        if domain not in stub_def.exempt_domains
    )
    
    # High-signal misclassifications (files marked as both stub and high-signal)
    misclassifications = [
        asdict(c) for c in all_classifications
        if c.is_stub and c.is_high_signal
    ]
    
    # Validation keys
    validation_keys = {
        "K1": "PASS" if canonical_stub_count == 0 else "FAIL",
        "K2": "PASS" if len(misclassifications) == 0 else "FAIL",
        "K3": "PASS",  # Scanner completed
    }
    
    result = StubAuditResult(
        timestamp=datetime.now().isoformat(),
        phase="3A",
        mode="read_only",
        stub_count_per_domain=stub_count_per_domain,
        canonical_stub_count=canonical_stub_count,
        total_files_scanned=len(all_classifications),
        stub_files=stub_files,
        high_signal_files=high_signal_files,
        exempt_files_count=exempt_count,
        allowlisted_files_count=allowlisted_count,
        high_signal_misclassifications=misclassifications,
        validation_keys=validation_keys,
    )
    
    # Write output
    OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    with OUTPUT_PATH.open("w", encoding="utf-8") as f:
        json.dump(asdict(result), f, indent=2)
    
    logging.debug(f"\n=== STUB AUDIT SUMMARY ===")
    logging.debug(f"Total files scanned: {result.total_files_scanned}")
    logging.debug(f"Canonical stub count: {result.canonical_stub_count}")
    logging.debug(f"High-signal files: {len(high_signal_files)}")
    logging.debug(f"Exempt files: {exempt_count}")
    logging.debug(f"Allowlisted files: {allowlisted_count}")
    logging.debug(f"Misclassifications: {len(misclassifications)}")
    
    logging.debug(f"\n=== VALIDATION KEYS ===")
    for key, status in validation_keys.items():
        logging.debug(f"{key} = {status}")
    
    return result


def main() -> int:
    """Main entry point."""
    try:
        result = run_stub_scan()
        
        # Return non-zero if canonical stubs exist
        if result.canonical_stub_count > 0:
            logging.debug(f"\n[FAIL] {result.canonical_stub_count} canonical stubs detected in non-exempt domains")
            return 1
        
        logging.debug("\n[PASS] No canonical stubs detected")
        return 0
    
    except Exception as e:
        logging.debug(f"[ERROR] Stub scan failed: {e}")
        import traceback
        traceback.print_exc()
        return 1


if __name__ == "__main__":
    sys.exit(main())
